"""既存の単語の復習レベルと次回復習予定日時を、過去の復習履歴から計算し直す

0003 で項目を追加した直後は、既存の単語がすべて「レベル0・予定日時=マイグレーション実行時刻」になる。
ここで ReviewLog を古い順に再生し、新しいアルゴリズムで復習していた場合と同じ状態にする。
ReviewLog そのものは読むだけで、変更・削除はしない。

※ マイグレーションは「実行した時点のルール」で動き続ける必要があるため、
  vocab/scheduling.py は import せず、当時の間隔をここに書き写している。
"""
from datetime import timedelta

from django.db import migrations

REVIEW_INTERVAL_DAYS = {1: 1, 2: 3, 3: 7, 4: 14, 5: 30}
MAX_LEVEL = 5
INCORRECT_INTERVAL_DAYS = 1


def rebuild_review_schedule(apps, schema_editor):
    Word = apps.get_model('vocab', 'Word')
    ReviewLog = apps.get_model('vocab', 'ReviewLog')

    for word in Word.objects.all():
        level = 0
        next_review_at = word.created_at  # 未復習の単語は登録時刻 = すぐに復習対象
        for log in ReviewLog.objects.filter(word=word).order_by('reviewed_at', 'pk'):
            if log.is_correct:
                level = min(level + 1, MAX_LEVEL)
                days = REVIEW_INTERVAL_DAYS[level]
            else:
                level = 0
                days = INCORRECT_INTERVAL_DAYS
            next_review_at = log.reviewed_at + timedelta(days=days)

        word.review_level = level
        word.next_review_at = next_review_at
        word.save(update_fields=['review_level', 'next_review_at'])


class Migration(migrations.Migration):

    dependencies = [
        ('vocab', '0003_word_review_schedule'),
    ]

    operations = [
        # 元に戻すとき（migrate vocab 0002）は 0003 で項目ごと消えるので、ここでは何もしない
        migrations.RunPython(rebuild_review_schedule, migrations.RunPython.noop),
    ]
